evidence=json.loads(Path('outputs/library-pcd-final-2026-10-11/source-index-verified.json').read_text(encoding='utf-8'));by={s['slug']:s for s in evidence};assert len(by)==24 and not any('error' in s for s in evidence)
for n,slug in refs.items():units['art-'+str(n)]['remissoes']=[by[slug]['url']]
